    if (Math.abs(u - .17) < .05) etiq('tum', x + w * .5 - 22, y + h * .5 - 14, AM); if (Math.abs(u - .5) < .05) etiq('tá', x + w * .5 - 14, y + h * .5 - 14, AM);
